// Determine the registry to use:
// 1. If `registry` is explicitly passed in options, use it (takes precedence)
// 2. If `formats` is an array, create a registry with only those formats
// 3. Otherwise, use the default registry from Quill.DEFAULTS
let registry: Parchment.Registry;
if (config.registry) {
  registry = config.registry;
} else if (Array.isArray(config.formats)) {
  registry = createRegistryWithFormats(
    config.formats,
    globalRegistry,
    debug,
  );
} else {
  registry = globalRegistry;
}

return {
  ...config,
  container,
  theme,
  modules: Object.entries(modules).reduce(
    (modulesWithDefaults, [name, value]) => {
      if (!value) return modulesWithDefaults;

      const moduleClass = Quill.import(`modules/${name}`);
      if (moduleClass == null) {
        debug.error(
          `Cannot load ${name} module. Are you sure you registered it?`,
        );
        return modulesWithDefaults;
      }
      return {
        ...modulesWithDefaults,
        // @ts-expect-error
        [name]: merge({}, moduleClass.DEFAULTS || {}, value),
      };
    },
    {},
  ),
  bounds: resolveSelector(config.bounds),
  registry,
};

